<?php declare(strict_types=1); require_once dirname(__DIR__,2).'/lib/tool-page.php'; $tool=['title'=>'JWT Decoder','description'=>'Decode JWT header and payload locally without sending tokens to a server.','url'=>'https://smarttoolz.in/tools/jwt-decoder/']; smarttoolz_tool_page_start($tool); ?><main class="tool"><h1>JWT Decoder</h1><p>Decode a JSON Web Token header and payload locally.</p><textarea id="in" placeholder="Paste JWT here"></textarea><button id="go">Decode JWT</button><pre id="out"></pre></main><style>.tool{max-width:760px;margin:60px auto;padding:24px}.tool textarea{width:100%;min-height:140px;box-sizing:border-box;padding:14px;border:1px solid #ddd;border-radius:12px}.tool button{margin-top:12px;padding:12px 18px;border:0;border-radius:10px;background:#5541ff;color:#fff;font-weight:800}.tool pre{margin-top:16px;padding:16px;background:#f6f7fb;border-radius:12px;white-space:pre-wrap;word-break:break-word}</style><script>const i=document.getElementById('in'),o=document.getElementById('out');document.getElementById('go').onclick=()=>{try{const a=i.value.trim().split('.');if(a.length<2)throw Error();const d=x=>JSON.stringify(JSON.parse(decodeURIComponent(escape(atob(x.replace(/-/g,'+').replace(/_/g,'/'))))),null,2);o.textContent='Header:\n'+d(a[0])+'\n\nPayload:\n'+d(a[1])}catch(e){o.textContent='Invalid JWT format or JSON.'}}</script><?php smarttoolz_tool_page_end(); ?>